import { mkdir, writeFile } from 'node:fs/promises'
import path from 'node:path'

export interface InitWorkspaceOptions {
  targetDir: string
  force?: boolean
}

export interface InitWorkspaceResult {
  workspaceRoot: string
  filesWritten: string[]
}

const WORKSPACE_DIRS = [
  '.chain-insights',
  '.chain-insights/schema',
  '.chain-insights/runtime',
  '.chain-insights/runtime-skill',
  'cases',
  'imports',
  'logs',
  'reports',
  'reports/graphs',
  'reports/tables',
  'templates',
]

function todayIso(): string {
  return new Date().toISOString().slice(0, 10)
}

function workspaceJson(workspaceRoot: string): string {
  return JSON.stringify({
    schema: 'chain-insights.workspace.v1',
    name: 'Chain Insights Investigations',
    workspace_root: workspaceRoot,
    default_network: 'bittensor',
    graph_mcp_endpoint: 'https://staging-mcp.chain-insights.ai/mcp',
    cases_dir: 'cases',
    imports_dir: 'imports',
    reports_dir: 'reports',
    templates_dir: 'templates',
    created_at: todayIso(),
  }, null, 2) + '\n'
}

